"""Chapter 2 Kinematics explanation bank extension (6091 LOs 2a-2i): 10 per level, every LO at least twice.
Ideas adapted from the question bank (SEAB 2014-2025 MCQs on graphs, free fall, parachutists; school papers 2024-2025)."""
from .. import figs, sketches
from .base import X, explain_bank


def g(pts, ylabel="speed / m/s", xmax=None, ymax=None, labels=None):
    xs, ys = zip(*pts)
    return lambda: figs.graph(pts, xmax or max(xs), ymax or max(ys) * 1.25 + 1, max(1, round(max(xs) / 6)), max(1, round(max(ys) * 1.25 / 5)), ylabel=ylabel, labels=labels)


